import {request,getSession,ensureSession} from './client.js';
import {parseCSV} from './csv.mjs';
import {textileSeed} from './textile-reference.mjs';
import {requirementStates,colorFamilies,supplierStates,keyText,kg,pendingKg,kgLabel,safeLink,folderId,verifiedAvailability,requestNumber,catalogHeaders,normalizeCatalogRows,stockAlerts} from './textile-domain.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tables={suppliers:'textile_suppliers',yarns:'textile_yarns',colors:'textile_colors',stock:'textile_stock',requirements:'textile_requirements',photos:'textile_photos',folders:'textile_drive_folders',history:'textile_history',notifications:'textile_notifications',runs:'textile_sync_runs'};
const tabs=[['textile','Panel textil'],['colors','Carta de colores'],['yarns','Hilos y almacén'],['suppliers','Proveedores'],['requirements','Requerimiento de hilos'],['photos','Fotografías'],['integrations','Conexiones y actualización'],['textile-history','Historial textil']];
const adminTabs=['textile','requirements','integrations','textile-history'];
const date=v=>!v?'Pendiente':/^\d{4}-\d{2}-\d{2}$/.test(String(v))?String(v).split('-').reverse().join('/'):new Date(v).toLocaleDateString('es-PE',{timeZone:'America/Lima'});
const options=(rows,value,label,selected='',blank='Selecciona')=>'<option value="">'+esc(blank)+'</option>'+rows.map(r=>'<option value="'+esc(r[value])+'" '+(String(r[value])===String(selected)?'selected':'')+'>'+esc(typeof label==='function'?label(r):r[label])+'</option>').join('');
const input=(name,label,value='',type='text',extra='')=>'<label>'+label+'<input name="'+name+'" type="'+type+'" value="'+esc(value??'')+'" '+extra+'></label>';
const checkbox=(name,label,checked=false)=>'<label class="checkbox"><input type="checkbox" name="'+name+'" '+(checked?'checked':'')+'>'+label+'</label>';
function download(rows,name){if(!rows.length)throw new Error('No hay registros para exportar.');const keys=Object.keys(rows[0]),safe=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const url=URL.createObjectURL(new Blob(['\uFEFF'+[keys.join(','),...rows.map(r=>keys.map(k=>safe(r[k])).join(','))].join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
let excelReady;
async function spreadsheetRows(file){if(file.size>5_000_000)throw new Error('El catálogo debe pesar menos de 5 MB.');if(/\.csv$/i.test(file.name)){const rows=parseCSV((await file.text()).replace(/^\uFEFF/,'')),headers=rows.shift();return rows.filter(r=>r.some(v=>v.trim())).map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]||''])));}if(!/\.xlsx$/i.test(file.name))throw new Error('Usa Excel .xlsx o CSV.');if(!excelReady)excelReady=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='/vendor/exceljs.min.js';script.onload=resolve;script.onerror=()=>reject(new Error('No se pudo cargar el lector de Excel.'));document.head.append(script);});await excelReady;const workbook=new window.ExcelJS.Workbook();await workbook.xlsx.load(await file.arrayBuffer());const sheet=workbook.worksheets[0];if(!sheet||sheet.rowCount>501)throw new Error('Usa una primera hoja de hasta 500 registros y encabezados.');const text=c=>{const v=c.value;if(v instanceof Date)return v.toISOString().slice(0,10);return v?.richText?v.richText.map(x=>x.text).join(''):v?.text??v?.result??(v instanceof Date?v.toISOString():v)??'';};const headers=sheet.getRow(1).values.slice(1).map(v=>String(v||'').trim()),rows=[];for(let i=2;i<=sheet.rowCount;i++){const row=Object.fromEntries(headers.map((h,j)=>[h,text(sheet.getRow(i).getCell(j+1))]));if(Object.values(row).some(v=>String(v).trim()))rows.push(row);}return rows;}
export function createTextileController(ctx){
 let data={suppliers:[],yarns:[],colors:[],stock:[],requirements:[],photos:[],folders:[],history:[],notifications:[],runs:[]},loaded=false,error='',busy=false,current='textile',query='',filters={},page=1,selected=[],serverStatus=null;
 const urls=new Map();let observer;
 const admin=()=>ctx.profile?.role==='admin',stage=()=>window.EURO_CONFIG?.textilePreview?'preview':'production';
 const local=()=>!ctx.connected;
 const active=(key)=>data[key].filter(r=>r.active!==false&&!r.deleted_at);
 const yarn=c=>data.yarns.find(y=>y.id===c.yarn_id)||{};
 const supplier=c=>data.suppliers.find(s=>s.id===(c.supplier_id||yarn(c).supplier_id))||{};
 const stock=c=>data.stock.find(s=>s.color_id===c.id&&!s.deleted_at)?.stock_kg??null;
 const photo=c=>active('photos').find(p=>p.color_id===c.id&&p.verification_status==='verified'&&p.rights_confirmed&&p.source_identity?.code===c.code&&p.source_identity?.yarn_id===c.yarn_id&&p.source_identity?.composition===yarn(c).composition&&p.source_identity?.title===yarn(c).title&&p.source_identity?.fiber===yarn(c).fiber&&p.source_identity?.provider===supplier(c).name);
 const newID=()=>crypto.randomUUID();
 async function api(action,body){await ensureSession();const r=await fetch('/api/textile?action='+action,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+getSession()?.access_token,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw new Error(d.error||'No se pudo completar la operación');return d;}
 async function load(){if(local()){if(!loaded)seed();return;}try{const results=await Promise.all(Object.entries(tables).map(async([key,table])=>{if(!admin()&&['requirements','folders','history','notifications','runs'].includes(key))return [key,[]];let all=[],offset=0;do{const rows=await request(table+'?stage=eq.'+stage()+'&select=*&order='+(['history','notifications','runs'].includes(key)?'created_at.desc':'id')+'&limit=1000&offset='+offset);all.push(...rows);if(rows.length<1000)break;offset+=1000;if(offset>=10000)break;}while(true);return [key,all];}));data=Object.fromEntries(results);loaded=true;error='';}catch(e){error='El módulo textil no está listo para esta conexión: '+e.message;}}
 function seed(){data=textileSeed(ctx.items);loaded=true;error='';}
 async function reload(){await load();ctx.render();}
 async function run(fn){if(busy)return;busy=true;document.querySelectorAll('dialog button[type=submit]').forEach(b=>b.disabled=true);try{await fn();}catch(e){ctx.toast(e.message,true);}finally{busy=false;document.querySelectorAll('dialog button[type=submit]').forEach(b=>b.disabled=false);}}
 async function save(key,body,old){if(!admin())throw new Error('Solo administradora');if(local()){const row={...body,id:old?.id||newID(),stage:stage(),updated_at:new Date().toISOString()};if(old)Object.assign(old,row);else data[key].push(row);data.history.unshift({id:newID(),stage:stage(),entity:tables[key],entity_id:row.id,operation:old?'UPDATE':'INSERT',current:{...row},actor:ctx.profile.id,created_at:new Date().toISOString()});if(key==='stock')for(const req of data.requirements.filter(r=>r.color_id===body.color_id&&!['Cancelado','Recibido completamente'].includes(r.status))){req.available_kg=body.stock_kg;req.pending_kg=pendingKg(req.required_kg,body.stock_kg);}return row;}const [row]=await request(tables[key]+(old?'?id=eq.'+old.id+'&stage=eq.'+stage():''),{method:old?'PATCH':'POST',body:old?body:{...body,stage:stage()}});return row;}
 const searchRows=(rows,text)=>rows.filter(r=>(!query||keyText(text(r)).includes(keyText(query))));
 function filteredColors(){return searchRows(data.colors.filter(c=>!c.deleted_at),c=>[c.name,c.code,yarn(c).name,yarn(c).fiber,c.collection,supplier(c).name].join(' ')).filter(c=>(filters.inactive==='all'||c.active!==false)&&(!filters.supplier||supplier(c).id===filters.supplier)&&(!filters.fiber||yarn(c).fiber===filters.fiber)&&(!filters.family||c.family===filters.family));}
 function filteredYarns(){return searchRows(active('yarns'),y=>[y.name,y.code,y.composition,y.title,supplier(y).name].join(' ')).filter(y=>!filters.supplier||y.supplier_id===filters.supplier);}
 function filteredRequirements(){return searchRows(data.requirements.filter(r=>!r.deleted_at),r=>{const c=data.colors.find(c=>c.id===r.color_id)||{};return [requestNumber(r),r.collection,r.model_name,r.model_code,c.name,yarn(c).name,r.responsible].join(' ');}).filter(r=>!filters.status||r.status===filters.status);}
 function filteredPhotos(){return searchRows(active('photos'),p=>[p.name,p.model_code,p.collection,data.yarns.find(y=>y.id===p.yarn_id)?.name,data.colors.find(c=>c.id===p.color_id)?.name].join(' ')).filter(p=>(!filters.kind||p.kind===filters.kind)&&(!filters.collection||p.collection===filters.collection)&&(!filters.supplier||data.yarns.find(y=>y.id===p.yarn_id)?.supplier_id===filters.supplier)&&(!filters.yarn||p.yarn_id===filters.yarn)&&(!filters.color||p.color_id===filters.color));}
 function tools(extra='',actions=''){return '<div class="textile-tools"><label class="search">⌕ <input id="textile-search" value="'+esc(query)+'" placeholder="Buscar por nombre, código o colección…" aria-label="Buscar en la sección textil"></label>'+extra+'<div class="textile-tool-actions"><button class="secondary" data-t-action="refresh">↻ Actualizar</button>'+actions+'</div></div>';}
 function selectFilter(key,label,values){return '<select data-t-filter="'+key+'" aria-label="'+esc(label)+'">'+options(values,'value','label',filters[key]||'',label)+'</select>';}
 function pagination(rows){const max=Math.max(1,Math.ceil(rows.length/12));page=Math.min(page,max);return '<div class="pagination"><span>'+rows.length+' registros · página '+page+' de '+max+'</span><div><button class="page-button" data-t-page="-1" '+(page===1?'disabled':'')+'>← Anterior</button><button class="page-button" data-t-page="1" '+(page===max?'disabled':'')+'>Siguiente →</button></div></div>';}
 const slice=rows=>{page=Math.min(page,Math.max(1,Math.ceil(rows.length/12)));return rows.slice((page-1)*12,page*12);};
 function image(p,cls='',size='thumb'){return p?'<button class="textile-photo '+cls+'" data-t-photo="'+p.id+'" aria-label="Ampliar '+esc(p.name)+'"><img data-private-photo="'+p.id+'" data-photo-size="'+size+'" alt="'+esc(p.name)+'" loading="lazy" decoding="async"><span>Ampliar ↗</span></button>':'<div class="photo-pending '+cls+'"><span>◇</span><small>Fotografía pendiente</small></div>';}
 function availability(c){const v=verifiedAvailability(c);return '<span class="badge '+(v==='Disponible confirmado'?'green':v==='No disponible confirmado'?'red':'amber')+'">'+esc(v)+'</span>';}
 function stockBadge(r){return r.pending_kg==null?'<span class="badge amber">Confirmar stock interno</span>':Number(r.pending_kg)>0?'<span class="badge red">Hilo insuficiente</span>':'<span class="badge green">Cubierto con stock</span>';}
 function dashboard(){const req=data.requirements.filter(r=>!r.deleted_at),pending=req.filter(r=>requirementStates.slice(0,3).includes(r.status)),orders=req.filter(r=>['Orden de compra emitida','En tránsito','Recibido parcialmente'].includes(r.status)),approved=req.filter(r=>requirementStates.slice(3,7).includes(r.status)),alerts=stockAlerts(req);const counts=active('suppliers').map(s=>({name:s.name,count:active('yarns').filter(y=>y.supplier_id===s.id).length}));const cards=[['Colores registrados',active('colors').length],['Hilos registrados',active('yarns').length],['Requerimientos pendientes',pending.length],['Requerimientos aprobados',approved.length],['Órdenes por recibir',orders.length],['Hilos insuficientes',new Set(alerts.map(r=>r.color_id)).size]];
 return ctx.heading('Control textil','Colores, proveedores y planificación de materiales conectados a tu colección.')+'<div class="textile-stats">'+cards.map(([l,n])=>'<article class="stat"><div>'+l+'</div><strong>'+n+'</strong></article>').join('')+'</div><div class="textile-dashboard-grid"><section class="panel padded"><h2>Hilos por proveedor</h2>'+counts.map(s=>'<div class="textile-chart-row"><span>'+esc(s.name)+'</span><div><i style="width:'+Math.max(1,s.count/Math.max(1,...counts.map(c=>c.count))*100)+'%"></i></div><b>'+s.count+'</b></div>').join('')+'</section><section class="panel padded"><h2>Seguimiento de producción</h2>'+requirementStates.map(state=>'<div class="textile-state-row"><span>'+state+'</span><b>'+req.filter(r=>r.status===state).length+'</b></div>').join('')+'</section></div><section class="panel padded"><h2>Materiales que requieren atención</h2>'+(alerts.length?alerts.map(r=>'<button class="textile-alert" data-t-requirement="'+r.id+'"><span>'+esc(requestNumber(r))+' · '+esc(r.model_name)+'</span><b>Faltan '+kgLabel(r.pending_kg)+'</b></button>').join(''):'<p>No hay faltantes confirmados. Los stocks sin conteo permanecen pendientes.</p>')+data.notifications.filter(n=>!n.read_at&&!n.deleted_at).map(n=>'<div class="textile-alert"><span><b>'+esc(n.title)+'</b><small>'+esc(n.message)+'</small></span><button class="secondary" data-t-read="'+n.id+'">Marcar leído</button><button class="danger secondary" data-t-delete="notifications" data-delete-id="'+n.id+'">Eliminar aviso</button></div>').join('')+'</section><section class="panel padded"><h2>Última actualización por proveedor</h2>'+active('suppliers').map(s=>'<div class="textile-state-row"><span>'+esc(s.name)+'</span><small>Catálogo: '+date(s.last_catalog_at)+' · Consulta: '+date(s.last_checked_at)+'</small></div>').join('')+'</section>';
 }
 function colorPage(){const rows=filteredColors(),supplierOptions=active('suppliers').map(s=>({value:s.id,label:s.name})),fibers=[...new Set(active('yarns').map(y=>y.fiber).filter(Boolean))].map(s=>({value:s,label:s}));return ctx.heading('Carta de colores','Color Library · Fotografías reales y referencias de cada hilo.',admin()?'<button class="primary" data-t-action="new-color">＋ Agregar color</button>':'')+tools(selectFilter('supplier','Todos los proveedores',supplierOptions)+selectFilter('fiber','Todas las fibras',fibers)+selectFilter('family','Todas las familias',colorFamilies.map(v=>({value:v,label:v})))+(admin()?selectFilter('inactive','Activos',[{value:'all',label:'Incluir desactivados'}]):''),(admin()?'<button class="secondary" data-t-action="photo-review">Actualizar fotografías pendientes</button>':'')+'<button class="secondary" data-t-action="compare" '+(selected.length<2?'disabled':'')+'>Comparar '+selected.length+'</button>')+'<div class="color-library-grid">'+slice(rows).map(c=>'<article class="color-library-card '+(!c.active?'inactive':'')+'">'+image(photo(c))+'<div class="color-library-info"><small>'+esc(supplier(c).name)+'</small><h2>'+esc(c.name)+'</h2><p class="color-reference">'+esc(c.code||'Código por confirmar')+'</p><p>'+esc(yarn(c).name)+'<small>'+esc(yarn(c).composition)+'</small></p><div class="color-card-meta"><span>'+esc(c.family)+'</span><span>'+esc(c.collection||'Colección por asignar')+'</span></div>'+availability(c)+'<div class="color-card-actions"><label class="checkbox"><input type="checkbox" data-t-compare="'+c.id+'" '+(selected.includes(c.id)?'checked':'')+'>Comparar</label><button class="text-button" data-t-color="'+c.id+'">Ver ficha ↗</button></div></div></article>').join('')+'</div>'+(rows.length?'':'<div class="empty">No hay colores con estos filtros.</div>')+pagination(rows);}
 function yarnPage(){const rows=filteredYarns();return ctx.heading('Hilos y almacén','Referencias técnicas y stock interno en kilogramos.',admin()?'<button class="primary" data-t-action="new-yarn">＋ Registrar hilo</button>':'')+tools(selectFilter('supplier','Todos los proveedores',active('suppliers').map(s=>({value:s.id,label:s.name}))))+'<div class="yarn-library-grid">'+slice(rows).map(y=>{const colors=active('colors').filter(c=>c.yarn_id===y.id),known=colors.map(stock).filter(v=>v!==null),photo=active('photos').find(p=>p.yarn_id===y.id&&!p.color_id);return '<article class="panel yarn-card">'+image(photo)+'<div class="padded"><small>'+esc(supplier(y).name)+'</small><h2>'+esc(y.name)+'</h2><p>'+esc(y.code||'Referencia por confirmar')+' · '+esc(y.title||'Título por confirmar')+'</p><p>'+esc(y.composition||'Composición pendiente')+'</p><div class="textile-state-row"><span>'+colors.length+' colores</span><b>'+kgLabel(known.length?known.reduce((a,b)=>a+Number(b),0):null)+'</b></div><small>'+(known.length<colors.length?'Conteo interno incompleto':'Stock interno confirmado por color')+'</small><button class="secondary full" data-t-yarn="'+y.id+'">Ver hilo y colores ↗</button></div></article>';}).join('')+'</div>'+pagination(rows);}
 function supplierPage(){return ctx.heading('Proveedores de hilos','Yarn Suppliers · Consulta las fuentes originales y registra información verificada.')+tools('','')+'<div class="supplier-grid">'+active('suppliers').map(s=>'<article class="panel supplier-card"><div class="supplier-monogram">'+esc(s.name.slice(0,1))+'</div><h2>'+esc(s.name)+'</h2><span class="badge amber">'+esc(s.integration_status)+'</span><p>'+esc(s.integration_notes)+'</p><div class="supplier-links">'+(safeLink(s.website)?'<a class="secondary" href="'+esc(safeLink(s.website))+'" target="_blank" rel="noopener">Web oficial ↗</a>':'')+(safeLink(s.catalog_url)?'<a class="secondary" href="'+esc(safeLink(s.catalog_url))+'" target="_blank" rel="noopener">Catálogo original ↗</a>':'')+'</div><dl class="detail-grid"><div><dt>HILOS REGISTRADOS</dt><dd>'+active('yarns').filter(y=>y.supplier_id===s.id).length+'</dd></div><div><dt>CATÁLOGO ACTUALIZADO</dt><dd>'+date(s.last_catalog_at)+'</dd></div></dl>'+(admin()?'<div class="supplier-links"><button class="primary" data-t-import="'+s.id+'">Importar Excel / CSV</button><button class="secondary" data-t-supplier="'+s.id+'">Editar</button></div>':'')+'</article>').join('')+'</div>'+(admin()?'<section class="panel padded"><h2>Actualización autorizada</h2><p>Las consultas automáticas se activan únicamente para API o archivos periódicos autorizados. Mientras falte ese acceso, la disponibilidad permanece pendiente de confirmación.</p><button class="secondary" data-tab="integrations">Revisar conexiones ↗</button></section>':'');}
 function requirementsPage(){const rows=filteredRequirements();return ctx.heading('Requerimiento de hilos','Yarn Requirements · Planifica compras y controla cada entrega. El cálculo por solicitud no reserva automáticamente otros materiales.','<button class="primary" data-t-action="new-requirement">＋ Nuevo requerimiento</button>')+tools(selectFilter('status','Todos los estados',requirementStates.map(v=>({value:v,label:v}))),'<button class="secondary" data-t-action="export-requirements">↓ Exportar</button>')+'<section class="panel textile-table-wrap"><table class="textile-table"><thead><tr><th>Requerimiento / modelo</th><th>Hilo / color</th><th>Requerido</th><th>Stock interno</th><th>Por comprar</th><th>Estado</th><th></th></tr></thead><tbody>'+slice(rows).map(r=>{const c=data.colors.find(c=>c.id===r.color_id)||{};return '<tr><td>'+esc(requestNumber(r))+'<small>'+esc(r.model_name)+' · '+esc(r.collection)+'</small></td><td>'+esc(yarn(c).name)+'<small>'+esc(c.name)+' · '+esc(supplier(c).name)+'</small></td><td>'+kgLabel(r.required_kg)+'</td><td>'+kgLabel(r.available_kg)+'</td><td class="'+(r.pending_kg>0?'textile-shortage':'')+'">'+kgLabel(r.pending_kg)+'</td><td><span class="badge">'+esc(r.status)+'</span><small>'+date(r.expected_on)+'</small></td><td><button class="row-action" data-t-requirement="'+r.id+'" aria-label="Ver requerimiento">↗</button></td></tr>';}).join('')+(rows.length?'':'<tr><td colspan="7"><div class="empty">Todavía no hay requerimientos. Registra el primero para planificar tus materiales.</div></td></tr>')+'</tbody></table>'+pagination(rows)+'</section>';}
 function photosPage(){const rows=filteredPhotos();return ctx.heading('Fotografías textiles','Colecciones, modelos y referencias · Imágenes privadas dentro de EUROALPACA.',admin()?'<button class="primary" data-t-action="upload">＋ Subir fotografía</button>':'')+tools(selectFilter('kind','Todos los tipos',['producto','hilo','color','referencia'].map(v=>({value:v,label:v})))+selectFilter('collection','Todas las colecciones',[...new Set(active('photos').map(p=>p.collection).filter(Boolean))].map(v=>({value:v,label:v})))+selectFilter('supplier','Todos los proveedores',active('suppliers').map(v=>({value:v.id,label:v.name})))+selectFilter('yarn','Todos los hilos',active('yarns').map(v=>({value:v.id,label:v.name})))+selectFilter('color','Todos los colores',active('colors').map(v=>({value:v.id,label:v.name}))))+'<div class="photo-library-grid">'+slice(rows).map(p=>'<article class="panel photo-library-card">'+image(p)+'<div class="padded"><h2>'+esc(p.name)+'</h2><small>'+esc(p.model_code||p.collection||'Sin vincular')+' · '+esc(p.kind)+'</small><small>'+esc(p.visibility==='admin'?'Solo administradora':'Equipo autorizado')+'</small>'+(admin()?'<button class="text-button" data-t-photo-edit="'+p.id+'">Vincular / editar</button>':'')+'</div></article>').join('')+'</div>'+(rows.length?'':'<section class="panel empty">Aún no hay fotografías vinculadas.<small>Conecta una carpeta de Drive o sube fotografías con autorización de uso.</small></section>')+pagination(rows);}
 function integrationPage(){return ctx.heading('Conexiones y actualización','Carpetas autorizadas, catálogos revisados y seguimiento de sincronizaciones.')+'<div class="textile-dashboard-grid"><section class="panel padded"><h2>Google Drive</h2><p>'+(serverStatus?.drive.configured?'Cuenta de servicio lista: comparte las carpetas elegidas como Lector con <b>'+esc(serverStatus.drive.email)+'</b>.':'La cuenta de servicio está pendiente de configurar en el servidor. Tus archivos no se harán públicos.')+'</p><button class="secondary" data-t-action="connection-status">Comprobar conexión</button><button class="primary" data-t-action="new-folder">＋ Vincular carpeta</button><p class="panel-note">La sincronización recorre subcarpetas y mantiene las relaciones por modelo, hilo o color. Las imágenes sin coincidencia clara quedan sin vincular.</p></section><section class="panel padded"><h2>Fuentes de proveedores</h2><p>La importación Excel/CSV permite revisar el catálogo antes de guardarlo. Las imágenes de proveedores requieren autorización de uso.</p><p>'+(serverStatus?.feeds.length?serverStatus.feeds.length+' fuentes autorizadas configuradas.':'Sin API autorizada configurada. Usa la actualización manual.')+'</p><button class="secondary" data-t-action="sync-suppliers">Consultar fuentes autorizadas</button><small>Sincronización programada: '+(serverStatus?.scheduled?'Habilitada':'Desactivada hasta configurar las fuentes')+'</small></section></div><section class="panel padded"><div class="panel-head"><h2>Carpetas vinculadas</h2><button class="secondary" data-t-action="sync-drive">↻ Sincronizar Drive</button></div>'+data.folders.filter(f=>!f.deleted_at).map(f=>'<div class="folder-row"><div><b>'+esc(f.name)+'</b><small>'+esc(f.collection||f.model_code||f.kind)+' · '+esc(f.visibility==='admin'?'Solo administradora':'Equipo autorizado')+' · '+(f.active?'Activa':'Desactivada')+'</small><small>Última sincronización: '+date(f.last_synced_at)+'</small>'+(f.last_error?'<small class="textile-shortage">'+esc(f.last_error)+'</small>':'')+'</div><button class="secondary" data-t-folder="'+f.id+'">Editar</button><button class="secondary" data-t-sync-folder="'+f.id+'">Sincronizar</button></div>').join('')+(data.folders.length?'':'<p>No se ha vinculado ninguna carpeta.</p>')+'</section><section class="panel padded"><h2>Últimas sincronizaciones</h2>'+data.runs.filter(r=>!r.deleted_at).slice(0,12).map(r=>'<div class="textile-state-row"><span>'+esc(r.source)+' · '+esc(r.status)+'</span><small>'+date(r.created_at)+'</small><button class="danger secondary" data-t-delete="runs" data-delete-id="'+r.id+'">Eliminar</button></div>').join('')+'</section>';}
 function historyPage(){const rows=searchRows(data.history,h=>h.entity+' '+h.operation);const labels={textile_colors:'Color',textile_yarns:'Hilo',textile_requirements:'Requerimiento',textile_stock:'Stock interno',textile_photos:'Fotografía',textile_drive_folders:'Carpeta Drive',textile_suppliers:'Proveedor'};return ctx.heading('Historial textil','Registro de altas, cambios y actualizaciones.')+tools()+'<section class="panel textile-table-wrap"><table class="textile-table"><thead><tr><th>Fecha</th><th>Registro</th><th>Acción</th><th>Detalle</th></tr></thead><tbody>'+slice(rows).map(h=>'<tr><td>'+date(h.created_at)+'</td><td>'+esc(labels[h.entity]||h.entity)+'</td><td>'+esc(h.operation==='INSERT'?'Registro creado':'Actualización')+'</td><td><button class="text-button" data-t-history="'+h.id+'">Ver cambios ↗</button></td></tr>').join('')+'</tbody></table>'+pagination(rows)+'</section>';}
 function content(tab){current=tab;if(!loaded||error)return ctx.heading('Gestión textil','Ampliación de EUROALPACA')+'<section class="panel empty">'+esc(error||'Cargando referencias textiles…')+'<button class="secondary" data-t-action="refresh">Reintentar</button></section>';if(adminTabs.includes(tab)&&!admin())return ctx.heading('Acceso administrativo','Esta sección está disponible para la administradora.');return ({textile:dashboard,colors:colorPage,yarns:yarnPage,suppliers:supplierPage,requirements:requirementsPage,photos:photosPage,integrations:integrationPage,'textile-history':historyPage}[tab]||dashboard)();}
 function colorDetail(c){const y=yarn(c),s=supplier(c),p=photo(c);const d=ctx.modal(c.name,'<div class="textile-detail-layout">'+image(p,'detail-photo','full')+'<section><p class="eyebrow">'+esc(s.name)+'</p><h3>'+esc(c.code||'Código por confirmar')+'</h3><dl class="detail-grid">'+[['Hilo',y.name],['Material',y.fiber],['Composición',y.composition],['Título',y.title],['Familia cromática',c.family],['Colección',c.collection||'Por asignar'],['Stock interno',kgLabel(stock(c))],['Disponibilidad del proveedor',verifiedAvailability(c)],['Fecha de verificación',date(c.availability_verified_at)],['Fotografía',p?'Verificada':'Pendiente'],['Consulta de la fotografía',date(p?.source_checked_at)],['Autorización / autoría',p?.permission_reference]].map(([l,v])=>'<div><dt>'+l+'</dt><dd>'+esc(v||'Pendiente')+'</dd></div>').join('')+'</dl><p class="panel-note">'+esc(y.source_note)+'</p>'+(p?.source_url?.startsWith('https://')?'<a href="'+esc(safeLink(p.source_url))+'" target="_blank" rel="noopener noreferrer">Fuente oficial de la fotografía ↗</a>':'')+(admin()?'<div class="dialog-actions"><button class="secondary" id="color-upload">Cargar fotografía real</button><button class="secondary" id="color-stock">Confirmar stock en kg</button><button class="primary" id="edit-color">Editar color</button></div>':'')+'</section></div>',true);ctx.attachDelete?.(d,'textile_colors',c,'color');d.querySelector('#edit-color')?.addEventListener('click',()=>{d.close();colorForm(c);});d.querySelector('#color-upload')?.addEventListener('click',()=>{d.close();photoForm(null,{name:y.name+' · '+c.code,kind:'color',color_id:c.id,yarn_id:y.id,collection:c.collection,visibility:'team'});});d.querySelector('#color-stock')?.addEventListener('click',()=>{d.close();stockForm(c);});hydrateImages();}
 function colorForm(c){const y=yarn(c||{}),s=supplier(c||{});const d=ctx.modal(c?'Editar color':'Agregar color','<form id="textile-color-form"><div class="form-grid"><label class="span-2">Hilo / proveedor<select name="yarn_id" '+(c?'disabled':'required')+'>'+options(active('yarns'),'id',y=>supplier(y).name+' · '+y.name+' · '+y.composition,c?.yarn_id)+'</select></label>'+input('name','Nombre comercial',c?.name||'','text','required')+input('code','Código del proveedor',c?.code||'')+'<label>Familia cromática<select name="family">'+colorFamilies.map(f=>'<option '+(f===c?.family?'selected':'')+'>'+f+'</option>').join('')+'</select></label>'+input('collection','Colección / línea',c?.collection||'')+'<label class="span-2">Disponibilidad del proveedor<select name="supplier_availability">'+supplierStates.map(v=>'<option '+(v===(c?.supplier_availability||supplierStates[0])?'selected':'')+'>'+v+'</option>').join('')+'</select></label>'+input('availability_date','Fecha de confirmación',c?.availability_verified_at?.slice(0,10)||'','date')+input('availability_source','Fuente de la confirmación',c?.availability_source||'')+checkbox('active','Color activo',c?.active!==false)+checkbox('confirmed','Revisé y confirmé la disponibilidad indicada',false)+'</div><p class="panel-note">Una disponibilidad confirmada exige fecha y fuente. Las fichas del inventario permanecen pendientes hasta verificarlas.</p><div class="dialog-actions"><button type="submit" class="primary">Guardar color</button></div></form>',true);ctx.attachDelete?.(d,'textile_colors',c,'color');d.querySelector('form').onsubmit=e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target),status=f.get('supplier_availability'),name=String(f.get('name')).trim(),yarn_id=c?.yarn_id||f.get('yarn_id'),code=String(f.get('code')).trim();if(!name||!yarn_id)throw new Error('Selecciona hilo y nombre del color.');const existing=data.colors.find(x=>x.id!==c?.id&&x.yarn_id===yarn_id&&(keyText(x.name)===keyText(name)||code&&keyText(x.code)===keyText(code)));if(existing)throw new Error('Este color ya está registrado para el hilo. Edita su ficha.');if(status!==supplierStates[0]&&(!f.has('confirmed')||!f.get('availability_date')||!f.get('availability_source')))throw new Error('Confirma fecha y fuente de disponibilidad.');if(f.get('availability_date')&&Date.parse(f.get('availability_date'))>Date.now())throw new Error('La fecha de verificación no puede estar en el futuro.');await save('colors',{yarn_id,name,code,reference_key:c?.reference_key||keyText(code||name),family:f.get('family'),collection:String(f.get('collection')).trim(),active:f.has('active'),supplier_availability:status,availability_verified_at:status===supplierStates[0]?null:new Date(f.get('availability_date')+'T12:00:00Z').toISOString(),availability_source:status===supplierStates[0]?'':String(f.get('availability_source')).trim()},c);await load();d.close();ctx.render();ctx.toast('Color guardado');});};}
 function yarnDetail(y){const colors=active('colors').filter(c=>c.yarn_id===y.id);const d=ctx.modal(y.name,'<p class="eyebrow">'+esc(supplier(y).name)+'</p><p>'+esc(y.composition)+'</p><p>'+esc(y.title)+' · '+esc(y.technical_notes)+'</p><p class="panel-note">'+esc(y.source_note)+'</p><section class="textile-table-wrap"><table class="textile-table"><thead><tr><th>Color</th><th>Código</th><th>Stock interno</th><th>Proveedor</th><th></th></tr></thead><tbody>'+colors.map(c=>'<tr><td>'+esc(c.name)+'</td><td>'+esc(c.code||'Por confirmar')+'</td><td>'+kgLabel(stock(c))+'</td><td>'+availability(c)+'</td><td>'+(admin()?'<button class="secondary" data-t-stock="'+c.id+'">Contar kg</button>':'')+'</td></tr>').join('')+'</tbody></table></section>'+(admin()?'<div class="dialog-actions"><button class="primary" id="edit-yarn">Editar hilo</button></div>':''),true);ctx.attachDelete?.(d,'textile_yarns',y,'hilo');d.querySelector('#edit-yarn')?.addEventListener('click',()=>{d.close();yarnForm(y);});d.querySelectorAll('[data-t-stock]').forEach(b=>b.onclick=()=>{d.close();stockForm(data.colors.find(c=>c.id===b.dataset.tStock));});}
 function yarnForm(y){const d=ctx.modal(y?'Editar hilo':'Registrar hilo','<form><div class="form-grid"><label>Proveedor<select name="supplier_id" required '+(y?'disabled':'')+'>'+options(active('suppliers'),'id','name',y?.supplier_id)+'</select></label>'+input('name','Nombre del hilo',y?.name||'','text','required')+input('code','Referencia del hilo',y?.code||'')+input('fiber','Tipo de fibra / material',y?.fiber||'')+input('composition','Composición',y?.composition||'')+input('title','Título del hilo',y?.title||'')+input('collection','Colección / temporada',y?.collection||'')+input('source_url','Enlace de referencia autorizado',y?.source_url||'','url')+'<label class="span-2">Características técnicas<textarea name="technical_notes">'+esc(y?.technical_notes)+'</textarea></label>'+checkbox('active','Hilo activo',y?.active!==false)+'</div><div class="dialog-actions"><button type="submit" class="primary">Guardar hilo</button></div></form>',true);ctx.attachDelete?.(d,'textile_yarns',y,'hilo');d.querySelector('form').onsubmit=e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target),body=Object.fromEntries(['name','code','fiber','composition','title','collection','technical_notes'].map(k=>[k,String(f.get(k)||'').trim()]));body.supplier_id=y?.supplier_id||f.get('supplier_id');body.reference_key=y?.reference_key||keyText(body.code||body.name)+'|'+keyText(body.title)+'|'+keyText(body.composition);body.active=f.has('active');body.source_url=safeLink(f.get('source_url'));body.source_note=y?.source_note||'Registro manual de administración';if(!body.name||!body.supplier_id)throw new Error('Completa nombre y proveedor.');if(!y&&data.yarns.some(x=>x.supplier_id===body.supplier_id&&x.reference_key===body.reference_key))throw new Error('La referencia ya existe. Edita el hilo registrado.');await save('yarns',body,y);await load();d.close();ctx.render();ctx.toast('Hilo guardado');});};}
 function stockForm(c){const previous=data.stock.find(s=>s.color_id===c.id);const d=ctx.modal('Stock interno de hilo','<p>'+esc(yarn(c).name)+' · '+esc(c.name)+'</p><form>'+input('stock_kg','Cantidad final contada en almacén (kg)',previous?.stock_kg??'','number','min="0" step="0.001" placeholder="Sin conteo confirmado"')+input('notes','Motivo / documento del conteo','','text','required minlength="3"')+'<p class="panel-note">Este valor corresponde al hilo de este color. No modifica las cantidades de prendas ni la disponibilidad del proveedor.</p><div class="dialog-actions"><button type="submit" class="primary">Confirmar stock</button></div></form>');ctx.attachDelete?.(d,'textile_stock',previous,'conteo');d.querySelector('form').onsubmit=e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target);await save('stock',{color_id:c.id,stock_kg:kg(f.get('stock_kg'),{nullable:true}),verified_at:new Date().toISOString(),notes:String(f.get('notes')).trim()},previous);await load();d.close();ctx.render();ctx.toast('Stock interno actualizado');});};}
 function requirementForm(r){const models=[...new Map(ctx.items.map(i=>[i.model_code,{id:i.model_code,name:i.name}])).values()];const d=ctx.modal(r?'Editar requerimiento':'Nuevo requerimiento','<form id="textile-requirement-form"><div class="form-grid">'+input('requested_on','Fecha de solicitud',r?.requested_on||new Date().toLocaleDateString('en-CA',{timeZone:'America/Lima'}),'date','required')+input('collection','Colección / temporada',r?.collection||'','text','required')+'<label class="span-2">Modelo de prenda<select name="model_code" required>'+options(models,'id',m=>m.id+' · '+m.name,r?.model_code)+'</select></label><label class="span-2">Hilo, proveedor y color<select name="color_id" required>'+options(active('colors'),'id',c=>supplier(c).name+' · '+yarn(c).name+' · '+c.name+(c.code?' · '+c.code:''),r?.color_id)+'</select></label>'+input('required_kg','Cantidad requerida (kg)',r?.required_kg||'','number','required min="0.001" step="0.001"')+input('expected_on','Fecha estimada de entrega',r?.expected_on||'','date')+input('responsible','Responsable',r?.responsible||ctx.profile.full_name||'','text','required')+'<label>Estado<select name="status">'+requirementStates.map(state=>'<option '+(state===(r?.status||requirementStates[0])?'selected':'')+' '+(['Recibido parcialmente','Recibido completamente'].includes(state)&&state!==r?.status?'disabled':'')+'>'+state+'</option>').join('')+'</select></label><div class="span-2 requirement-calculation" id="requirement-calculation"></div><label class="span-2">Observaciones<textarea name="notes">'+esc(r?.notes)+'</textarea></label></div><div class="dialog-actions"><button type="submit" class="primary">Guardar requerimiento</button></div></form>',true);ctx.attachDelete?.(d,'textile_requirements',r,'requerimiento');const form=d.querySelector('form');function calculate(){const c=data.colors.find(c=>c.id===form.elements.color_id.value),available=c?stock(c):null;let remaining=null;try{remaining=pendingKg(form.elements.required_kg.value,available);}catch{}d.querySelector('#requirement-calculation').innerHTML='<div><small>Stock interno confirmado</small><b>'+kgLabel(available)+'</b></div><div><small>Pendiente de compra</small><b class="'+(remaining>0?'textile-shortage':'')+'">'+kgLabel(remaining)+'</b></div>'+(c?'<small>'+esc(yarn(c).composition)+' · '+esc(verifiedAvailability(c))+'</small>':'');}form.elements.color_id.onchange=calculate;form.elements.required_kg.oninput=calculate;calculate();form.onsubmit=e=>{e.preventDefault();run(async()=>{const f=new FormData(form),model=models.find(m=>m.id===f.get('model_code'));if(!model||!f.get('color_id'))throw new Error('Selecciona modelo y color del hilo.');if(f.get('expected_on')&&f.get('expected_on')<f.get('requested_on'))throw new Error('La entrega no puede ser anterior a la solicitud.');const body={requested_on:f.get('requested_on'),collection:String(f.get('collection')).trim(),model_code:model.id,model_name:model.name,color_id:f.get('color_id'),required_kg:kg(f.get('required_kg'),{positive:true}),expected_on:f.get('expected_on')||null,responsible:String(f.get('responsible')).trim(),status:f.get('status'),notes:String(f.get('notes')).trim()};if(local()){const c=data.colors.find(c=>c.id===body.color_id);body.available_kg=stock(c);body.pending_kg=pendingKg(body.required_kg,body.available_kg);body.purchase_kg=r?.purchase_kg??null;if(['Orden de compra emitida','En tránsito','Recibido parcialmente','Recibido completamente'].includes(body.status)&&body.purchase_kg===null){if(body.available_kg===null)throw new Error('Confirma el stock interno antes de emitir la orden.');body.purchase_kg=body.pending_kg;}body.sequence=r?.sequence||data.requirements.length+1;body.received_kg=r?.received_kg||0;}await save('requirements',body,r);await load();d.close();ctx.render();ctx.toast('Requerimiento guardado');});};}
 function requirementDetail(r){const c=data.colors.find(c=>c.id===r.color_id)||{},y=yarn(c);const d=ctx.modal(requestNumber(r),'<div class="textile-detail-layout">'+image(photo(c),'detail-photo')+'<section><h3>'+esc(r.model_name)+' · '+esc(r.model_code)+'</h3>'+stockBadge(r)+'<dl class="detail-grid">'+[['Solicitud',r.requested_on],['Colección',r.collection],['Hilo',y.name],['Referencia',y.code],['Composición',y.composition],['Proveedor',supplier(c).name],['Color',c.name],['Código de color',c.code],['Requerido',kgLabel(r.required_kg)],['Stock interno',kgLabel(r.available_kg)],['Por comprar',kgLabel(r.pending_kg)],['Cantidad de la orden',kgLabel(r.purchase_kg)],['Recibido',kgLabel(r.received_kg||0)],['Entrega estimada',r.expected_on],['Responsable',r.responsible],['Estado',r.status]].map(([l,v])=>'<div><dt>'+l+'</dt><dd>'+esc(v||'Pendiente')+'</dd></div>').join('')+'</dl><p>'+esc(r.notes)+'</p><div class="dialog-actions"><button class="secondary" id="requirement-edit">Editar</button><button class="primary" id="requirement-receive" '+(!['Orden de compra emitida','En tránsito','Recibido parcialmente'].includes(r.status)?'disabled':'')+'>Registrar recepción</button></div></section></div>',true);ctx.attachDelete?.(d,'textile_requirements',r,'requerimiento');d.querySelector('#requirement-edit').onclick=()=>{d.close();requirementForm(r);};d.querySelector('#requirement-receive').onclick=()=>{d.close();receiveForm(r);};hydrateImages();}
 function receiveForm(r){const id=newID(),d=ctx.modal('Recepción de hilo','<p>'+esc(requestNumber(r))+' · '+esc(r.model_name)+'</p><form>'+input('amount','Cantidad recibida ahora (kg)','','number','required min="0.001" step="0.001"')+'<p class="panel-note">Se añade al stock interno y se registra la recepción parcial o completa. Confirma antes el conteo inicial del hilo.</p><div class="dialog-actions"><button type="submit" class="primary">Confirmar recepción</button></div></form>');d.querySelector('form').onsubmit=e=>{e.preventDefault();run(async()=>{const amount=kg(new FormData(e.target).get('amount'),{positive:true});if(local()){const s=data.stock.find(s=>s.color_id===r.color_id);if(s?.stock_kg==null)throw new Error('Confirma primero el stock interno.');if(Number(r.received_kg||0)+amount>Number(r.purchase_kg))throw new Error('La recepción supera la cantidad de la orden.');await save('stock',{color_id:s.color_id,stock_kg:Number(s.stock_kg)+amount,verified_at:new Date().toISOString(),notes:'Recepción '+requestNumber(r)},s);r.received_kg=Number(r.received_kg||0)+amount;r.status=r.received_kg===Number(r.purchase_kg)?'Recibido completamente':'Recibido parcialmente';}else await request('rpc/textile_receive',{method:'POST',body:{p_requirement:r.id,p_amount:amount,p_request:id}});await load();d.close();ctx.render();ctx.toast('Recepción registrada');});};}
 function photoFields(p={}){const models=[...new Map(ctx.items.map(i=>[i.model_code,{id:i.model_code,name:i.name}])).values()];return '<div class="form-grid">'+input('name','Nombre de referencia',p.name||'','text','required')+'<label>Tipo<select name="kind">'+['producto','hilo','color','referencia'].map(k=>'<option '+(k===(p.kind||'producto')?'selected':'')+'>'+k+'</option>').join('')+'</select></label>'+input('collection','Colección',p.collection||'')+'<label>Visibilidad<select name="visibility"><option value="admin" '+(p.visibility!=='team'?'selected':'')+'>Solo administradora</option><option value="team" '+(p.visibility==='team'?'selected':'')+'>Equipo con acceso al sistema</option></select></label><label>Modelo<select name="model_code">'+options(models,'id',m=>m.id+' · '+m.name,p.model_code,'Sin vincular a un modelo')+'</select></label><label>Hilo<select name="yarn_id">'+options(active('yarns'),'id',y=>supplier(y).name+' · '+y.name,p.yarn_id,'Sin vincular a un hilo')+'</select></label><label class="span-2">Color del hilo<select name="color_id">'+options(active('colors'),'id',c=>supplier(c).name+' · '+yarn(c).name+' · '+c.name,p.color_id,'Sin vincular a un color')+'</select></label>'+checkbox('rights_confirmed','Tengo autorización para usar estas fotografías dentro de EUROALPACA',p.rights_confirmed)+input('permission_reference','Autorización de uso o autoría (si se vincula a un color)',p.permission_reference||'')+checkbox('exact_confirmed','He comprobado que la foto corresponde al proveedor, hilo, código, composición y título del color',p.verification_status==='verified')+checkbox('active','Activo',p.active!==false)+'</div>';}
 function photoValues(form){const f=new FormData(form),color=data.colors.find(c=>c.id===f.get('color_id'));return {name:String(f.get('name')).trim(),kind:f.get('kind'),collection:String(f.get('collection')).trim(),visibility:f.get('visibility'),model_code:f.get('model_code')||'',yarn_id:color?.yarn_id||f.get('yarn_id')||null,color_id:f.get('color_id')||null,rights_confirmed:f.has('rights_confirmed'),active:f.has('active'),permission_reference:String(f.get('permission_reference')||'').trim(),exact_confirmed:f.has('exact_confirmed')};}
 function photoForm(p,defaults={}){const d=ctx.modal(p?'Vincular fotografía':'Subir fotografía','<form id="textile-photo-form">'+(!p?'<label>Fotografía real<input name="file" type="file" accept="image/jpeg,image/png,image/webp,image/avif" required></label>':'')+photoFields(p||defaults)+'<p class="panel-note">Las imágenes no se publican de forma abierta. Se conservan con los permisos elegidos y versiones optimizadas para consulta y ampliación.</p><div class="dialog-actions"><button type="submit" class="primary">Guardar fotografía</button></div></form>',true);ctx.attachDelete?.(d,'textile_photos',p,'fotografía');d.querySelector('form').onsubmit=e=>{e.preventDefault();run(async()=>{const body=photoValues(e.target);if(!body.rights_confirmed)throw new Error('Confirma la autorización de uso.');if(body.color_id&&(!body.exact_confirmed||body.permission_reference.length<5))throw new Error('Comprueba la coincidencia exacta e indica la autorización o autoría.');if(p){const {exact_confirmed,...values}=body;await save('photos',values,p);}else{const f=new FormData(e.target).get('file');if(!f?.size||f.size>3_000_000)throw new Error('Elige una foto JPG, PNG, WebP o AVIF de hasta 3 MB.');if(!['image/jpeg','image/png','image/webp','image/avif'].includes(f.type))throw new Error('Formato no admitido.');if(local()){const id=newID(),url=URL.createObjectURL(f);const c=data.colors.find(c=>c.id===body.color_id),y=c?yarn(c):{},sp=c?supplier(c):{};await save('photos',{...body,id,_url:url,...(c?{verification_status:'verified',source_checked_at:new Date().toISOString(),source_identity:{color_id:c.id,yarn_id:y.id,provider:sp.name,code:c.code,composition:y.composition,title:y.title,fiber:y.fiber}}:{})});data.photos.at(-1)._url=url;}else{const dataURL=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(f);});await api('upload',{...body,mime_type:f.type,data:String(dataURL).split(',')[1]});}}await load();d.close();ctx.render();ctx.toast('Fotografía guardada');});};}
 async function imageURL(p,size){if(p._url)return p._url;const key=p.id+'|'+p.updated_at+'|'+size;if(urls.has(key))return urls.get(key);await ensureSession();const r=await fetch('/api/textile?action=media&id='+p.id+'&size='+size,{headers:{Authorization:'Bearer '+getSession()?.access_token},cache:'no-store'});if(!r.ok)throw new Error('Fotografía pendiente o acceso restringido');const url=URL.createObjectURL(await r.blob());if(urls.size>=80){const first=urls.keys().next().value;URL.revokeObjectURL(urls.get(first));urls.delete(first);}urls.set(key,url);return url;}
 function hydrateImages(){observer?.disconnect();const load=async img=>{const p=data.photos.find(p=>p.id===img.dataset.privatePhoto);if(!p)return;try{img.src=await imageURL(p,img.dataset.photoSize||'thumb');img.classList.add('ready');}catch{img.closest('.textile-photo')?.classList.add('unavailable-photo');img.alt='Fotografía pendiente o con acceso restringido';}};observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){observer.unobserve(entry.target);load(entry.target);}},{rootMargin:'400px'});document.querySelectorAll('[data-private-photo]').forEach(img=>observer.observe(img));document.querySelectorAll('[data-t-photo]').forEach(b=>b.onclick=()=>lightbox(data.photos.find(p=>p.id===b.dataset.tPhoto)));}
 function lightbox(p){if(!p)return;const d=ctx.modal(p.name,'<div class="photo-zoom-tools"><span>Observa los detalles del tejido</span><label>Ampliación<input type="range" min="100" max="250" step="25" value="100" id="photo-zoom"></label></div><div class="photo-zoom-viewport"><img id="photo-zoom-image" data-private-photo="'+p.id+'" data-photo-size="full" alt="'+esc(p.name)+'"></div><p class="panel-note">'+esc(p.collection||p.model_code||'Referencia textil')+'</p>',true);d.querySelector('#photo-zoom').oninput=e=>{d.querySelector('#photo-zoom-image').style.width=e.target.value+'%';d.querySelector('#photo-zoom-image').style.maxWidth='none';};hydrateImages();}
 function compare(){const colors=selected.map(id=>data.colors.find(c=>c.id===id)).filter(Boolean);ctx.modal('Comparar colores','<div class="color-comparison">'+colors.map(c=>'<article>'+image(photo(c),'comparison-photo','full')+'<h3>'+esc(c.name)+'</h3><p>'+esc(c.code||'Código pendiente')+'</p><small>'+esc(supplier(c).name)+' · '+esc(yarn(c).name)+'</small><small>'+esc(yarn(c).composition)+'</small>'+availability(c)+'</article>').join('')+'</div>',true);hydrateImages();}
 function folderForm(f){const d=ctx.modal(f?'Editar carpeta vinculada':'Vincular Google Drive','<form>'+input('folder_url','Enlace de carpeta de Google Drive',f?'https://drive.google.com/drive/folders/'+f.folder_id:'','url','required')+photoFields(f)+'<p class="panel-note">La cuenta de servicio solo debe tener acceso de lectura a esta carpeta. No cambies su uso compartido a público. El modelo, hilo o color elegidos se aplican a las fotos nuevas de esta carpeta.</p><div class="dialog-actions"><button type="submit" class="primary">Guardar carpeta</button></div></form>',true);ctx.attachDelete?.(d,'textile_drive_folders',f,'vinculación');d.querySelector('form').onsubmit=e=>{e.preventDefault();run(async()=>{const body=photoValues(e.target);delete body.permission_reference;delete body.exact_confirmed;body.folder_id=folderId(new FormData(e.target).get('folder_url'));if(!body.rights_confirmed)throw new Error('Confirma la autorización de uso.');if(data.folders.some(x=>x.id!==f?.id&&x.folder_id===body.folder_id))throw new Error('Esta carpeta ya está vinculada.');await save('folders',body,f);await load();d.close();ctx.render();ctx.toast('Carpeta vinculada. Sincroniza cuando el acceso esté configurado.');});};}
 function supplierForm(s){const d=ctx.modal('Referencia de proveedor','<form>'+input('name','Nombre',s.name,'text','required')+input('website','Web oficial',s.website,'url')+input('catalog_url','Enlace de catálogo',s.catalog_url,'url')+'<label>Notas de integración<textarea name="integration_notes">'+esc(s.integration_notes)+'</textarea></label><div class="dialog-actions"><button type="submit" class="primary">Guardar referencia</button></div></form>');ctx.attachDelete?.(d,'textile_suppliers',s,'proveedor');d.querySelector('form').onsubmit=e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target);await save('suppliers',{name:String(f.get('name')).trim(),website:safeLink(f.get('website')),catalog_url:safeLink(f.get('catalog_url')),integration_notes:String(f.get('integration_notes')).trim()},s);await load();d.close();ctx.render();ctx.toast('Proveedor actualizado');});};}
 function importForm(s){const id=newID(),d=ctx.modal('Importar catálogo · '+s.name,'<form><label>Excel .xlsx o CSV<input type="file" name="file" accept=".xlsx,.csv" required></label><p class="panel-note">La primera hoja debe usar los encabezados de la plantilla. No se importa stock interno desde el catálogo del proveedor.</p><button type="button" class="secondary" id="catalog-template">Descargar plantilla CSV</button><div id="catalog-review"></div>'+checkbox('authorized','Tengo autorización para utilizar este catálogo')+checkbox('verified','Revisé la fuente y confirmé la disponibilidad indicada en el archivo')+'<div class="dialog-actions"><button type="button" class="secondary" id="catalog-preview">Revisar archivo</button><button type="submit" class="primary" id="catalog-confirm" disabled>Confirmar importación</button></div></form>',true);let rows;d.querySelector('#catalog-template').onclick=()=>download([Object.fromEntries(catalogHeaders.map(k=>[k,'']))],'EUROALPACA-catalogo-plantilla.csv');d.querySelector('[name=file]').onchange=()=>{rows=null;d.querySelector('#catalog-confirm').disabled=true;d.querySelector('#catalog-review').innerHTML='';};d.querySelector('#catalog-preview').onclick=()=>run(async()=>{const file=d.querySelector('[name=file]').files[0];if(!file)throw new Error('Selecciona un archivo.');rows=normalizeCatalogRows(await spreadsheetRows(file));if(!rows.length)throw new Error('El archivo no contiene registros.');d.querySelector('#catalog-review').innerHTML='<p><b>'+rows.length+' filas para '+esc(s.name)+'</b>. Los registros se actualizarán por referencia, sin duplicarlos.</p><div class="textile-table-wrap"><table class="textile-table"><thead><tr><th>Hilo</th><th>Composición</th><th>Color</th><th>Disponibilidad</th></tr></thead><tbody>'+rows.slice(0,10).map(r=>'<tr><td>'+esc(r.name)+'</td><td>'+esc(r.composition)+'</td><td>'+esc(r.color_name)+'</td><td>'+esc(r.supplier_availability)+'</td></tr>').join('')+'</tbody></table></div>';d.querySelector('#catalog-confirm').disabled=false;});d.querySelector('form').onsubmit=e=>{e.preventDefault();run(async()=>{if(!rows)throw new Error('Revisa el archivo primero.');if(!new FormData(e.target).has('authorized'))throw new Error('Confirma la autorización de uso del catálogo.');const verified=new FormData(e.target).has('verified');if(rows.some(r=>r.supplier_availability!==supplierStates[0])&&!verified)throw new Error('Confirma la revisión de las disponibilidades del archivo.');if(local()){for(const row of rows){let y=data.yarns.find(y=>y.supplier_id===s.id&&y.reference_key===row.reference_key);const body=Object.fromEntries(['reference_key','code','name','fiber','composition','title','technical_notes','collection','source_url','source_note'].map(k=>[k,row[k]]));y=await save('yarns',{...body,supplier_id:s.id,active:true,verified_at:verified?new Date().toISOString():null},y);if(row.color_name){let c=data.colors.find(c=>c.yarn_id===y.id&&c.reference_key===row.color_key);await save('colors',{yarn_id:y.id,reference_key:row.color_key,code:row.color_code,name:row.color_name,family:row.family,collection:row.collection,active:true,supplier_availability:verified?row.supplier_availability:supplierStates[0],availability_verified_at:verified?row.availability_verified_at:null,availability_source:verified?row.availability_source:''},c);}}s.last_catalog_at=new Date().toISOString();}else await request('rpc/textile_import',{method:'POST',body:{p_stage:stage(),p_supplier:s.id,p_rows:rows,p_verified:verified,p_request:id}});await load();d.close();ctx.render();ctx.toast('Catálogo actualizado');});};}
 function historyDetail(h){const labels={name:'Nombre',code:'Código',composition:'Composición',fiber:'Fibra',title:'Título del hilo',family:'Familia',collection:'Colección',supplier_availability:'Disponibilidad del proveedor',stock_kg:'Stock interno (kg)',required_kg:'Requerido (kg)',available_kg:'Disponible interno (kg)',pending_kg:'Pendiente de compra (kg)',status:'Estado',active:'Activo',visibility:'Visibilidad',responsible:'Responsable',expected_on:'Entrega estimada',received_kg:'Recibido (kg)',purchase_kg:'Cantidad de la orden (kg)',notes:'Observaciones'};const fields=Object.keys(labels).filter(k=>h.current?.[k]!==undefined&&(!h.previous||JSON.stringify(h.previous[k])!==JSON.stringify(h.current[k])));ctx.modal('Cambios registrados','<p>'+date(h.created_at)+' · '+esc(h.operation==='INSERT'?'Registro creado':'Actualización')+'</p><dl class="detail-grid">'+fields.map(k=>'<div><dt>'+labels[k]+'</dt><dd>'+esc(h.previous?.[k]??'Sin dato')+' → '+esc(h.current?.[k]??'Sin dato')+'</dd></div>').join('')+'</dl>',true);}
 function enter(tab){if(tab!==current){query='';filters={};page=1;}current=tab;}
 function exportRequirements(){download(filteredRequirements().map(r=>{const c=data.colors.find(c=>c.id===r.color_id)||{},y=yarn(c);return {requerimiento:requestNumber(r),fecha:r.requested_on,coleccion:r.collection,modelo:r.model_name,codigo_modelo:r.model_code,hilo:y.name,codigo_hilo:y.code,composicion:y.composition,proveedor:supplier(c).name,color:c.name,codigo_color:c.code,requerido_kg:r.required_kg,stock_interno_kg:r.available_kg,pendiente_compra_kg:r.pending_kg,recibido_kg:r.received_kg,entrega:r.expected_on,responsable:r.responsible,estado:r.status};}),'EUROALPACA-requerimientos.csv');}
 async function sync(action,body){if(local())throw new Error('Conecta el servidor de prueba para consultar las fuentes autorizadas.');const result=await api(action,body||{});await load();ctx.render();ctx.modal('Resultado de actualización','<div class="textile-sync-results">'+result.results.map(r=>'<article><b>'+esc(r.name||r.supplier||r.status)+'</b><p>'+esc(r.error||r.message||r.status)+'</p>'+(r.total!==undefined?'<small>'+r.total+' fotografías · '+r.added+' nuevas · '+r.changed+' actualizadas</small>':'')+'</article>').join('')+'</div>');}
 function bind(){document.querySelectorAll('[data-t-delete]').forEach(b=>b.onclick=()=>ctx.deleteRecord(tables[b.dataset.tDelete],[data[b.dataset.tDelete].find(r=>r.id===b.dataset.deleteId)],'registro'));document.querySelector('#textile-search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;query=e.target.value;page=1;ctx.render();const field=document.querySelector('#textile-search');field.focus();field.setSelectionRange(pos,pos);});document.querySelectorAll('[data-t-filter]').forEach(el=>el.onchange=()=>{filters[el.dataset.tFilter]=el.value;page=1;ctx.render();});document.querySelectorAll('[data-t-page]').forEach(b=>b.onclick=()=>{page+=Number(b.dataset.tPage);ctx.render();});
document.querySelectorAll('[data-t-color]').forEach(b=>b.onclick=()=>colorDetail(data.colors.find(c=>c.id===b.dataset.tColor)));document.querySelectorAll('[data-t-yarn]').forEach(b=>b.onclick=()=>yarnDetail(data.yarns.find(y=>y.id===b.dataset.tYarn)));document.querySelectorAll('[data-t-requirement]').forEach(b=>b.onclick=()=>requirementDetail(data.requirements.find(r=>r.id===b.dataset.tRequirement)));document.querySelectorAll('[data-t-photo-edit]').forEach(b=>b.onclick=()=>photoForm(data.photos.find(p=>p.id===b.dataset.tPhotoEdit)));document.querySelectorAll('[data-t-folder]').forEach(b=>b.onclick=()=>folderForm(data.folders.find(f=>f.id===b.dataset.tFolder)));document.querySelectorAll('[data-t-supplier]').forEach(b=>b.onclick=()=>supplierForm(data.suppliers.find(s=>s.id===b.dataset.tSupplier)));document.querySelectorAll('[data-t-import]').forEach(b=>b.onclick=()=>importForm(data.suppliers.find(s=>s.id===b.dataset.tImport)));document.querySelectorAll('[data-t-history]').forEach(b=>b.onclick=()=>historyDetail(data.history.find(h=>String(h.id)===b.dataset.tHistory)));
document.querySelectorAll('[data-t-compare]').forEach(el=>el.onchange=()=>{if(el.checked&&selected.length>=4){el.checked=false;return ctx.toast('Compara hasta cuatro colores.');}selected=el.checked?[...new Set([...selected,el.dataset.tCompare])]:selected.filter(id=>id!==el.dataset.tCompare);ctx.render();});
document.querySelectorAll('[data-t-read]').forEach(b=>b.onclick=()=>run(async()=>{const n=data.notifications.find(n=>n.id===b.dataset.tRead);if(local())n.read_at=new Date().toISOString();else await request('textile_notifications?id=eq.'+n.id+'&stage=eq.'+stage(),{method:'PATCH',body:{read_at:new Date().toISOString()}});await reload();}));document.querySelectorAll('[data-t-sync-folder]').forEach(b=>b.onclick=()=>run(()=>sync('sync-drive',{folder_id:b.dataset.tSyncFolder})));
const actions={'photo-review':openPhotoReport,refresh:reload,'new-color':()=>colorForm(),'new-yarn':()=>yarnForm(),'new-requirement':()=>requirementForm(),upload:()=>photoForm(),compare,'new-folder':()=>folderForm(),'export-requirements':exportRequirements,'connection-status':async()=>{serverStatus=local()?{drive:{configured:false,email:''},feeds:[],scheduled:false}:await api('status');ctx.render();},'sync-drive':()=>sync('sync-drive'),'sync-suppliers':()=>sync('sync-suppliers')};document.querySelectorAll('[data-t-action]').forEach(b=>b.onclick=()=>run(()=>actions[b.dataset.tAction]?.()));hydrateImages();}
 async function openPhotoReport(){const report=local()?{total:active('colors').length,found:0,verified:active('colors').filter(c=>photo(c)).length,pending:active('colors').filter(c=>!photo(c)).length,manual:active('colors').filter(c=>!photo(c)).length,errors:0,rows:active('colors').map(c=>({id:c.id,name:c.name,provider:supplier(c).name,yarn:yarn(c).name,code:c.code,composition:yarn(c).composition,title:yarn(c).title,verified:!!photo(c),reason:photo(c)?'Fotografía propia verificada.':c.code?'Consulta oficial disponible en el servidor conectado.':'Falta el código original. Requiere revisión manual.',candidates:[]}))}:await api('photo-report');showPhotoReport(report);}
 function showPhotoReport(report){const d=ctx.modal('Actualizar fotografías pendientes','<p class="panel-note">La búsqueda consulta únicamente fuentes oficiales conocidas, conserva sus resultados durante 24 horas y respeta las restricciones de acceso. Cada coincidencia necesita revisión y autorización antes de guardarse. Los datos originales de los colores se conservan.</p><div class="photo-report-stats">'+[['Colores',report.total],['Encontradas',report.found],['Verificadas y cargadas',report.verified],['Pendientes',report.pending],['Revisión manual',report.manual],['Errores',report.errors]].map(([label,n])=>'<div><strong>'+n+'</strong><small>'+label+'</small></div>').join('')+'</div><div class="dialog-actions"><button class="secondary" id="photo-report-export">Exportar reporte CSV</button><button class="primary" id="photo-discover" '+(local()?'disabled':'')+'>Buscar en fuentes oficiales</button></div><div class="textile-table-wrap"><table class="textile-table"><thead><tr><th>Proveedor / hilo / código</th><th>Resultado y motivo</th><th>Acciones</th></tr></thead><tbody>'+report.rows.map((r,index)=>'<tr><td>'+esc(r.provider)+'<br>'+esc(r.yarn)+' · <b>'+esc(r.code||'Sin código')+'</b><small>'+esc(r.name)+' · '+esc(r.composition)+' · '+esc(r.title)+'</small></td><td><span class="badge '+(r.verified?'green':'amber')+'">'+(r.verified?'Verificada':r.candidates.length?'Coincidencia por revisar':'Pendiente')+'</span><p>'+esc(r.reason)+'</p><small>'+esc(r.checked_at?date(r.checked_at):'Sin consulta registrada')+'</small></td><td>'+(!r.verified?r.candidates.map((candidate,k)=>'<button class="secondary" data-photo-candidate="'+index+'" data-candidate-index="'+k+'">Revisar coincidencia</button>').join('')+'<button class="text-button" data-manual-color="'+r.id+'">Cargar foto propia</button>':'')+'</td></tr>').join('')+'</tbody></table></div>',true);
 d.querySelector('#photo-discover').onclick=()=>run(async()=>{const b=d.querySelector('#photo-discover');b.disabled=true;b.textContent='Consultando fuentes…';try{const next=await api('photo-discover',{});d.close();showPhotoReport(next);}finally{b.disabled=false;b.textContent='Buscar en fuentes oficiales';}});
 d.querySelector('#photo-report-export').onclick=()=>download(report.rows.map(r=>({id:r.id,proveedor:r.provider,hilo:r.yarn,color:r.name,codigo:r.code,composicion:r.composition,titulo:r.title,estado:r.verified?'Verificada':'Pendiente',motivo:r.reason,coincidencias:r.candidates.length,consulta:r.checked_at||'',fuentes:r.candidates.map(c=>c.source_url).join(' | ')})),'EUROALPACA-fotografias-colores.csv');
 d.querySelectorAll('[data-photo-candidate]').forEach(b=>b.onclick=()=>{const row=report.rows[Number(b.dataset.photoCandidate)],index=Number(b.dataset.candidateIndex);d.close();reviewPhotoCandidate(row,index);});
 d.querySelectorAll('[data-manual-color]').forEach(b=>b.onclick=()=>{const c=data.colors.find(c=>c.id===b.dataset.manualColor);d.close();photoForm(null,{name:yarn(c).name+' · '+c.code,kind:'color',color_id:c.id,yarn_id:c.yarn_id,collection:c.collection,visibility:'team'});});
 }
 function reviewPhotoCandidate(row,index){const candidate=row.candidates[index],d=ctx.modal('Revisar fotografía oficial','<div class="textile-detail-layout"><div><img class="official-photo-review" src="'+esc(safeLink(candidate.image_url))+'" referrerpolicy="no-referrer" alt="Fuente oficial para revisar código '+esc(row.code)+'"><p class="panel-note">'+esc(candidate.crop?'Se guardará únicamente la muestra etiquetada con el código correspondiente en esta carta oficial.':'Comprueba la variante exacta antes de confirmar.')+'</p></div><section><h3>'+esc(row.provider)+' · '+esc(row.yarn)+' · '+esc(row.code)+'</h3><p>'+esc(row.composition)+' · '+esc(row.title)+'</p><p>'+esc(candidate.review||'Compara el código de la fotografía con los datos originales.')+'</p><a href="'+esc(safeLink(candidate.source_url))+'" target="_blank" rel="noopener noreferrer">Ver catálogo oficial ↗</a><form>'+input('permission_reference','Referencia de permiso de uso y evidencia técnica','','text','required minlength="5" maxlength="1500"')+checkbox('exact_confirmed','He verificado proveedor, hilo, código, título y composición completa en la documentación oficial')+checkbox('rights_confirmed','Tengo autorización del titular para guardar esta fotografía en EURO ALPACA')+'<p class="panel-note">Una imagen pública no implica permiso para copiarla. Si falta permiso o evidencia técnica, conserva la fotografía pendiente.</p><div class="dialog-actions"><button class="primary" type="submit">Confirmar y guardar fotografía</button></div></form></section></div>',true);
 d.querySelector('form').onsubmit=e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target);if(!f.has('exact_confirmed')||!f.has('rights_confirmed'))throw new Error('Confirma la coincidencia completa y el permiso del titular.');await api('photo-confirm',{color_id:row.id,candidate:index,exact_confirmed:true,rights_confirmed:true,permission_reference:f.get('permission_reference')});await load();d.close();ctx.render();ctx.toast('Fotografía verificada y guardada');await openPhotoReport();});};
 }

 function photosForModel(code){return active('photos').filter(p=>p.model_code===code&&p.kind==='producto'&&p.rights_confirmed).sort((a,b)=>String(a.name).localeCompare(String(b.name)));}
 function modelCover(code){const p=photosForModel(code)[0];return p?'<span class="model-private-cover"><img data-private-photo="'+p.id+'" alt="'+esc(p.name)+'" loading="lazy" decoding="async"></span>':'';}
 function modelPhotos(code){return photosForModel(code).map(p=>'<div class="model-photo-item">'+image(p)+'</div>').join('');}
 function destroy(){observer?.disconnect();for(const u of urls.values())URL.revokeObjectURL(u);for(const p of data.photos)if(p._url)URL.revokeObjectURL(p._url);urls.clear();loaded=false;selected=[];serverStatus=null;}
 return {load,seed,content,bind,enter,modelPhotos,modelCover,hydrateImages,destroy,has:tab=>tabs.some(([id])=>id===tab),nav:()=>tabs,data:()=>data};
}
